// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(uint256 value) public {
        vm.assume(value <= 2 ether);

        address actor = address(0x1);
        vm.deal(actor, type(uint256).max);

        bool ok;
        vm.prank(actor);
        try c.lockInGuess{value: value}(bytes32(0)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || value == 1 ether);
    }
}
